detaileddescription.para:
使用示例： //从字节数构造
byte_sizesize1(1024);
println(size1);//"1KB"

//从值和单位构造
byte_sizesize2(decimal_t(1.5),byte_size::unit::MB);
println(size2.bytes());//1572864

//从字符串解析
autosize3=byte_size::parse("2.5GB");
autosize4=byte_size::parse("1MiB",true);//二进制模式

//算术运算
byte_sizetotal=size1+size2;
byte_sizehalf=total/2;

//单位转换
doublein_mb=size2.as(byte_size::unit::MB);

//格式化输出
println(size2.to_string(byte_size::unit::KB,0));//"1536KB"
